using namespace std;

void shellSort(vector<int>& a) {
    int n = a.size();
    for (int gap = n / 2; gap > 0; gap /= 2) {
        for (int i = gap; i < n; i++) {
            int t = a[i], j = i;
            while (j >= gap && a[j - gap] > t) {
                a[j] = a[j - gap];
                j -= gap;
            }
            a[j] = t;
        }
    }
}

int main() {
    vector<int> a = {12, 34, 54, 2, 3};
    shellSort(a);
    for (int v : a) cout << v << " ";
